// Cloudflare entry: the Next.js app (built by OpenNext) plus a timer that plays due matches.
// @ts-ignore generated by `opennextjs-cloudflare build`
import { default as handler } from './.open-next/worker.js';

type KV = { get: (k: string) => Promise<string | null>; put: (k: string, v: string) => Promise<void> };
type Env = { WORKER_SELF_REFERENCE: { fetch: (r: Request) => Promise<Response>}; CRON_SECRET?: string; KORA?: KV };
const HOUR = 3_600_000;

export default {
  fetch: handler.fetch,
  // Every minute. The time of the next kick-off (or live match ending) is kept in KV, so most minutes
  // end here without touching the database and it can sleep between matches. Each call to /api/cron
  // is its own request with its own CPU budget.
  async scheduled(_event: unknown, env: Env, ctx: { waitUntil: (p: Promise<unknown>) => void }) {
    ctx.waitUntil((async () => {
      const now = Date.now();
      let saved: { next: number | null; at: number } | null = null;
      try { saved = JSON.parse((await env.KORA?.get('next_due')) || 'null'); } catch {}
      // nothing due yet (and a check at least every 6 hours, just in case)
      if (saved && now - saved.at < 6 * HOUR && (saved.next === null || now < saved.next - 20_000)) return;
      let nextDue: number | null | undefined;
      for (let i = 0; i < 40; i++) {
        const res = await env.WORKER_SELF_REFERENCE.fetch(new Request(`https://kora.internal/api/cron?key=${encodeURIComponent(env.CRON_SECRET || '')}`));
        if (!res.ok) { nextDue = undefined; break; }
        const j = (await res.json()) as { played: number; remaining: number; nextDue: number | null };
        nextDue = j.nextDue;
        if (!j.remaining || !j.played) break;
      }
      if (nextDue === undefined || !env.KORA) return; // something failed: try again next minute
      const next = nextDue === null ? null : Math.max(nextDue, now);
      if (saved?.next !== next || now - (saved?.at || 0) > HOUR) await env.KORA.put('next_due', JSON.stringify({ next, at: now }));
    })());
  },
};

// @ts-ignore re-exported for OpenNext features that use Durable Objects
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from './.open-next/worker.js';
